import { ImageScene } from "@/ascii/ImageSampler";

/** Generated by scripts/prepare_portrait.py. */
export const PORTRAIT_SRC = "/assets/portrait.png";

/** `aspect` is the image's width / height. */
function placement(width: number, height: number, aspect: number) {
  if (width < 768) {
    const w = Math.min(width * 1.1, height * 0.6 * aspect);
    const h = w / aspect;
    return { x: (width - w) / 2, y: height * 0.07, w, h };
  }
  // Anchored to the bottom edge, slightly right of centre.
  const h = height * 0.97;
  const w = h * aspect;
  return { x: width * 0.65 - w / 2, y: height - h, w, h };
}

export function loadPortraitScene() {
  return ImageScene.load(PORTRAIT_SRC, { placement, packed: true });
}
